import{_ as t,c as r,o,ag as a}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Player","description":"","frontmatter":{},"headers":[],"relativePath":"guide/player.md","filePath":"guide/player.md","lastUpdated":1791309864000}'),s={name:"guide/player.md"};function i(n,e,l,d,h,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="player" tabindex="-1">Player <a class="header-anchor" href="#player" aria-label="Permalink to &quot;Player&quot;">​</a></h1><p>nPlyr&#39;s player is a single <code>AVPlayer</code>-based core shared by macOS and iOS. This page covers the everyday controls and the platform-specific gestures.</p><h2 id="opening-something" tabindex="-1">Opening something <a class="header-anchor" href="#opening-something" aria-label="Permalink to &quot;Opening something&quot;">​</a></h2><p>From the home screen you can:</p><ul><li><strong>Open a file</strong> — drag a local video onto the window, or use the file picker.</li><li><strong>Open a URL</strong> — paste a direct link (<code>.mp4</code>, <code>.m3u8</code>, <code>.flv</code>, <code>.ts</code>, …) into the URL field.</li><li><strong>Open from the sniffer</strong> — send a captured link straight from the <a href="/guide/browser.html">Browser</a> drawer to the player.</li><li><strong>Open from a mini-program</strong> — tap a playable item and nPlyr resolves it through the <a href="/guide/miniapps.html">rule engine</a>.</li></ul><h2 id="common-controls-both-platforms" tabindex="-1">Common controls (both platforms) <a class="header-anchor" href="#common-controls-both-platforms" aria-label="Permalink to &quot;Common controls (both platforms)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>Play / Pause</td><td>Space (macOS) or tap the center of the video (iOS)</td></tr><tr><td>Seek</td><td>Scrub the progress bar, or use the platform gestures below</td></tr><tr><td>Volume</td><td>System / on-screen volume</td></tr><tr><td>Speed</td><td>0.5×–3× from the speed button</td></tr><tr><td>Audio track</td><td>Pick a track when the source has multiple</td></tr><tr><td>Subtitles</td><td>Load external <code>.srt</code> / <code>.vtt</code> or use embedded tracks</td></tr><tr><td>Picture-in-Picture</td><td>Pop the video into a floating PiP window</td></tr><tr><td>AirPlay</td><td>Send video to an Apple TV or AirPlay speaker</td></tr><tr><td>DLNA (macOS)</td><td>Cast to a DLNA renderer on your network</td></tr></tbody></table><h2 id="macos-gestures-shortcuts" tabindex="-1">macOS gestures &amp; shortcuts <a class="header-anchor" href="#macos-gestures-shortcuts" aria-label="Permalink to &quot;macOS gestures &amp; shortcuts&quot;">​</a></h2><h3 id="trackpad" tabindex="-1">Trackpad <a class="header-anchor" href="#trackpad" aria-label="Permalink to &quot;Trackpad&quot;">​</a></h3><ul><li><strong>Horizontal swipe</strong> scrubs the timeline. The new position is <strong>previewed</strong> while you drag; the actual seek happens when you lift your finger (or after a 250 ms pause), so a stray swipe never jumps the video.</li><li><strong>Vertical swipe</strong> adjusts <strong>brightness</strong> or <strong>volume</strong> depending on where you started: the <strong>left half</strong> of the video controls brightness, the <strong>right half</strong> controls volume. The first swipe locks the axis so the two never fight.</li><li><strong>Scroll wheel</strong> over the progress bar fine-tunes the position (±5% per notch).</li></ul><h3 id="brightness" tabindex="-1">Brightness <a class="header-anchor" href="#brightness" aria-label="Permalink to &quot;Brightness&quot;">​</a></h3><p>macOS does not expose a public API to dim another app&#39;s video, so nPlyr overlays a dimming layer between the video and the controls. This is purely cosmetic — the underlying picture is unchanged.</p><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h3><p>Shortcuts are matched on the <strong>modifier keys only</strong> (<code>⌘</code>, <code>⌥</code>, <code>⌃</code>, <code>⇧</code>) — direction keys and the numeric keypad are ignored for matching, so arrow-key bindings work reliably. Single-key shortcuts are suppressed while you are typing in a text field (the URL bar, search box, etc.).</p><p>If a shortcut ever stops working, see <a href="/guide/troubleshooting.html">Troubleshooting</a>.</p><h2 id="ios-gestures" tabindex="-1">iOS gestures <a class="header-anchor" href="#ios-gestures" aria-label="Permalink to &quot;iOS gestures&quot;">​</a></h2><ul><li><strong>Double-tap</strong> splits the screen into three zones: tap the <strong>left third</strong> to step back 10 s, the <strong>right third</strong> to step forward 10 s, and the <strong>center</strong> to play / pause (with a ripple at the tap point).</li><li><strong>Long-press (0.5 s)</strong> temporarily plays at <strong>2.0×</strong>; release to return to normal speed.</li><li>An <strong>edge dead-zone</strong> (about 30 pt, or 10% of the short side) is ignored so swipes that start at the bezel don&#39;t trigger gestures. The dead-zone is active only in fullscreen.</li></ul><h2 id="advanced-playback" tabindex="-1">Advanced playback <a class="header-anchor" href="#advanced-playback" aria-label="Permalink to &quot;Advanced playback&quot;">​</a></h2><h3 id="multi-source-video-json" tabindex="-1">Multi-source video JSON <a class="header-anchor" href="#multi-source-video-json" aria-label="Permalink to &quot;Multi-source video JSON&quot;">​</a></h3><p>Some rules return a structured JSON describing several video lines (different resolutions or CDNs), subtitles, lyrics and audio URLs. nPlyr parses this into a <strong>source switcher</strong> so you can flip between lines without losing your position.</p><h3 id="resume-source-switching" tabindex="-1">Resume &amp; source switching <a class="header-anchor" href="#resume-source-switching" aria-label="Permalink to &quot;Resume &amp; source switching&quot;">​</a></h3><ul><li>nPlyr remembers where you stopped and offers to <strong>resume</strong> next time.</li><li>When you switch sources mid-playback, the <strong>last frame is frozen</strong> for a moment during the swap so the screen doesn&#39;t flash black.</li><li>A seek issued before the item is ready is <strong>queued</strong> and applied the instant playback can start — so you never silently restart from the beginning.</li></ul><h3 id="progressive-playback" tabindex="-1">Progressive playback <a class="header-anchor" href="#progressive-playback" aria-label="Permalink to &quot;Progressive playback&quot;">​</a></h3><p>You can start watching while the file is still downloading. See <a href="/guide/downloads.html">Downloads &amp; Library</a>.</p>',24)])])}const g=t(s,[["render",i]]);export{p as __pageData,g as default};
